import{renderDiagram}from './visual.js?v=20261023-physicscomplete01';import{matterFigure}from './mat1-figures.js?v=20261023-physicscomplete01';export function showMat1(spec='charge',w={}){let[kind,card]=spec.split(':');renderDiagram(w.title||'Explore charge and matter',w.label||'Original educational model',matterFigure({kind,state:card||'0',...w}).replaceAll('mat1-warm','mat1-view-warm').replaceAll('mat1-cool','mat1-view-cool'),'PHYSICS · '+(['density','states'].some(k=>kind.startsWith(k))?'PARTICLE MODEL':'STATIC ELECTRICITY'));}
